<div class="card form-card"><form method="post" enctype="multipart/form-data" action="?page=masters&amp;type=<?=e($type)?>&amp;action=<?=$mode==='create'?'store':'update&amp;id='.(int)($row['id']??0)?>"><?=$csrfField?><input type="hidden" name="type" value="<?=e($type)?>"><div class="form-grid">
<label>Kode<input value="<?=e($row['code']??'')?>" readonly aria-readonly="true"></label>
<label>Nama<input name="name" value="<?=e($row['name']??'')?>" required><?php if(isset($errors['name'])):?><span class="field-error"><?=e($errors['name'])?></span><?php endif;?></label>
<?php if($type==='categories'):?><label class="full-field">Deskripsi<textarea name="description" rows="3" required><?=e($row['description']??'')?></textarea><?php if(isset($errors['description'])):?><span class="field-error"><?=e($errors['description'])?></span><?php endif;?></label><?php endif;?>
<?php if($type==='products'):?><label>Kategori<select name="category_id" required><option value="">Pilih kategori</option><?php foreach($categories as $category):?><option value="<?=$category['id']?>" <?=((int)($row['category_id']??0)===(int)$category['id'])?'selected':''?>><?=e($category['code'].' - '.$category['name'])?></option><?php endforeach;?></select><?php if(isset($errors['category_id'])):?><span class="field-error"><?=e($errors['category_id'])?></span><?php endif;?></label><label>Satuan<input name="unit" value="<?=e($row['unit']??'pcs')?>" required></label><label>Harga Beli<input type="number" min="0" step="0.01" name="purchase_price" value="<?=e($row['purchase_price']??0)?>"></label><label>Harga Jual<input type="number" min="0" step="0.01" name="selling_price" value="<?=e($row['selling_price']??0)?>"></label><label>Minimum Stok<input type="number" min="0" step="0.01" name="minimum_stock" value="<?=e($row['minimum_stock']??0)?>"></label><?php if(isset($errors['price'])):?><span class="field-error full-field" role="alert"><?=e($errors['price'])?></span><?php endif;?><label class="full-field">Gambar Produk (opsional)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG, atau WebP; maksimal 2 MB.</small><?php if(isset($errors['image'])):?><span class="field-error"><?=e($errors['image'])?></span><?php endif;?><?php if(!empty($row['image_path'])):?><img class="product-image-preview" src="<?=e($row['image_path'])?>" alt="Gambar <?=e($row['name']??'produk')?> saat ini"><?php endif;?></label><?php endif;?><?php if($type!=='products'&&$type!=='categories'):?><label>Alamat<textarea name="address"><?=e($row['address']??'')?></textarea></label><label>Telepon<input name="phone" value="<?=e($row['phone']??'')?>"></label><?php if(in_array($type,['customers','suppliers'],true)):?><label>Email<input type="email" name="email" value="<?=e($row['email']??'')?>"></label><?php endif;?><?php endif;?><label>Status<select name="status"><option value="Active" <?=($row['status']??'Active')==='Active'?'selected':''?>>Active</option><option value="Inactive" <?=($row['status']??'')==='Inactive'?'selected':''?>>Inactive</option></select></label></div><div class="form-actions"><a class="btn" href="?page=masters&amp;type=<?=e($type)?>">Batal</a><button class="btn btn-primary">Simpan</button></div></form></div>
